+function calculateNextReview(card: Flashcard, grade: number): Date {
+  const easiness = Math.max(1.3, card.easiness + 0.1 - (5 - grade) * (0.08 + (5 - grade) * 0.02));
+  const interval = card.interval === 0 ? 1 : card.interval === 1 ? 6 : Math.round(card.interval * easiness);
+  return addDays(new Date(), interval);
+}

