+export default defineConfig({
+  test: { environment: 'node', pool: 'forks' }
+});

+async function recordProgress(userId: number, cardId: number, correct: boolean): Promise<void> {
+  await db.prepare('INSERT INTO progress (user_id, card_id, correct, reviewed_at) VALUES (?, ?, ?, ?)').run(userId, cardId, correct ? 1 : 0, new Date().toISOString());
+  if (correct) await updateCardSchedule(userId, cardId);
+}

+// Extracted token validation from route handler into middleware
+export function requireAuth(req: Request, res: Response, next: NextFunction) {
+  const token = req.cookies.token ?? req.headers.authorization?.split(' ')[1];
+  if (!token) return res.status(401).end();
+  req.user = jwt.verify(token, process.env.JWT_SECRET) as JwtPayload;
+  next();
+}

+describe('calculateNextReview', () => {
+  it('returns 1 day for new card with grade 4', () => {
+    const next = calculateNextReview({ easiness: 2.5, interval: 0 }, 4);
+    expect(differenceInDays(next, new Date())).toBe(1);
+  });
+  it('increases interval for high grades', () => {
+    const next = calculateNextReview({ easiness: 2.5, interval: 6 }, 5);
+    expect(differenceInDays(next, new Date())).toBeGreaterThan(6);
+  });
+});

+async function getDueCards(userId: number): Promise<Flashcard[]> {
+  return db.prepare('SELECT * FROM flashcards WHERE user_id = ? AND next_review <= ? AND active = 1').all(userId, new Date().toISOString()) as Flashcard[];
+}
+export async function sendDueNotification(userId: number): Promise<void> {
+  const due = await getDueCards(userId);
+  if (due.length > 0) await notificationService.send(userId, \`You have ${due.length} cards due for review\`);
+}

