+router.post('/decks/:id/import', upload.single('file'), async (req, res) => {
+  const records = parse(req.file!.buffer, { columns: ['front', 'back'] });
+  const cards = await Promise.all(records.map(r => CardService.create({ ...r, deckId: req.params.id })));
+  res.json({ imported: cards.length });
+});

+async function apiFetch(url: string, options?: RequestInit) {
+  const res = await fetch(url, options);
+  if (res.status === 429) {
+    const retryAfter = Number(res.headers.get('Retry-After') ?? 1);
+    await sleep(retryAfter * 1000);
+    return fetch(url, options);
+  }
+  return res;
+}
